-- ================================================== -- MOTE HUB BETA 2.92 - FLOOR 2 ESP & DRAWER SCANNER FIXED -- ==================================================  local Players = game:GetService("Players") local VirtualUser = game:GetService("VirtualUser") local UserInputService = game:GetService("UserInputService") local RunService = game:GetService("RunService") local Workspace = game:GetService("Workspace") local Lighting = game:GetService("Lighting") local CoreGui = game:GetService("CoreGui") local StarterGui = game:GetService("StarterGui") local TweenService = game:GetService("TweenService")  local LocalPlayer = Players.LocalPlayer local Camera = Workspace.CurrentCamera  -------------------------------------------------- -- CẤU HÌNH TRẠNG THÁI (FLAGS) -------------------------------------------------- local Flags = {     AntiAFK = true,     MonsterNotify = true,     SmartFullbright = false,     FullbrightIntensity = 50,          ESPDoor = false,     ESPItems = false,     ESPMonster = false,     ESPLever = false,     ESPChest = false,     ESPPlayer = false,          AutoDrawersLoot = false,     AutoKeyDoor = false,          NoClip = false,     DoorsJump = false,     SpeedHack = false,     SpeedMultiplier = 1.0,     FreecamSoul = false,     FlyCarpet = false,          Language = "VIE",     Theme = "YellowBlack",     TextSize = 13 }  local OriginalLighting = {     Brightness = Lighting.Brightness,     ClockTime = Lighting.ClockTime,     FogEnd = Lighting.FogEnd,     GlobalShadows = Lighting.GlobalShadows,     Ambient = Lighting.Ambient,     OutdoorAmbient = Lighting.OutdoorAmbient }  -------------------------------------------------- -- PALETTE MÀU THEME MENU & MÀU ESP -------------------------------------------------- local Themes = {     YellowBlack = { FrameBg = Color3.fromRGB(15, 15, 15), HeaderBg = Color3.fromRGB(25, 25, 25), Accent = Color3.fromRGB(255, 215, 0), InnerBg = Color3.fromRGB(28, 28, 28), Text = Color3.fromRGB(255, 255, 255) },     RedBlack    = { FrameBg = Color3.fromRGB(15, 15, 15), HeaderBg = Color3.fromRGB(25, 25, 25), Accent = Color3.fromRGB(239, 68, 68), InnerBg = Color3.fromRGB(28, 28, 28), Text = Color3.fromRGB(255, 255, 255) },     GreenBlack  = { FrameBg = Color3.fromRGB(15, 15, 15), HeaderBg = Color3.fromRGB(34, 197, 94), InnerBg = Color3.fromRGB(28, 28, 28), Text = Color3.fromRGB(255, 255, 255) },     PinkBlack   = { FrameBg = Color3.fromRGB(15, 15, 15), HeaderBg = Color3.fromRGB(236, 72, 153), Accent = Color3.fromRGB(236, 72, 153), InnerBg = Color3.fromRGB(28, 28, 28), Text = Color3.fromRGB(255, 255, 255) } }  local ESPColors = {     Monster = Color3.fromRGB(255, 40, 40),     Door    = Color3.fromRGB(0, 255, 128),     Lever   = Color3.fromRGB(255, 255, 0),     Chest   = Color3.fromRGB(200, 100, 255),     Items   = Color3.fromRGB(0, 255, 255),     Player  = Color3.fromRGB(255, 140, 0) }  local Translations = {     VIE = { Main = "Main", ESP = "ESP", Automation = "Tự Động", Experimental = "Thử Nghiệm", Settings = "Cài Đặt", AntiAFK = "1. Anti-AFK", MonsterNotify = "2. Cảnh Báo Quái Vật", Fullbright = "3. Nhìn Trong Bóng Tối", AutoDrawers = "1. Auto Mở Tủ (3 Tủ) & Loot Đồ", AutoDoorKey = "2. Auto Mở Cửa Bằng Key", NoClip = "1. NoClip (Xuyên Tường)", Jump = "2. Nút Nhảy DOORS", Speed = "3. Speed Hack (Max x4)", Freecam = "4. Khảm Giả (Linh Hồn Tách Xác)", FlyCarpet = "5. Bay Sáng Tạo", ThemeTitle = "1. Đổi Màu Menu", LangTitle = "2. Ngôn Ngữ", FontSizeTitle = "3. Kích Thước Chữ", Author = "Tác Giả: By Mờ Tê", Facebook = "Facebook: Nguyễn minh tân", Version = "Phiên Bản: Mote Hub Beta 2.92" },     ENG = { Main = "Main", ESP = "ESP", Automation = "Automation", Experimental = "Experimental", Settings = "Settings", AntiAFK = "1. Anti-AFK", MonsterNotify = "2. Smart Monster Notify", Fullbright = "3. Fullbright", AutoDrawers = "1. Auto Open 3 Drawers & Auto Loot", AutoDoorKey = "2. Auto Key Door", NoClip = "1. NoClip", Jump = "2. DOORS Jump Button", Speed = "3. Speed Hack (Up to x4)", Freecam = "4. Freecam Soul (Spectate Fly)", FlyCarpet = "5. Creative Fly", ThemeTitle = "1. Change Theme", LangTitle = "2. Language", FontSizeTitle = "3. Text Size", Author = "Author: By Mote", Facebook = "Facebook: Nguyen minh tan", Version = "Version: Mote Hub Beta 2.92" } }  -------------------------------------------------- -- BẢNG DỮ LIỆU VẬT THỂ VÀ QUÁI VẬT (CẬP NHẬT FLOOR 1 & FLOOR 2) -------------------------------------------------- local ImportantItems = {     -- Key & Quest Items     ["KeyObtain"] = "🔑 Chìa Khóa", ["Key"] = "🔑 Chìa Khóa", ["MasterKey"] = "🔑 Chìa Khóa Master",     ["SkeletonKey"] = "💀 Chìa Khóa Đầu Lâu", ["LiveHintBook"] = "📘 Sách", ["FuseInPlainSight"] = "🔋 Cầu Chì",     ["Fuse"] = "🔋 Cầu Chì", ["Placard"] = "📜 Tấm Bảng", ["Anchor"] = "⚓ Mỏ Neo", ["MinesKey"] = "🔑 Chìa Khóa Mỏ",          -- Floor 1 Light & Healing     ["Flashlight"] = "🔦 Đèn Pin", ["Candle"] = "🕯️ Nến", ["Crucifix"] = "✝️ Cây Thánh Giá",     ["Lockpick"] = "🗝️ Lockpick", ["Bandage"] = "🩹 Băng Gạc", ["Vitamins"] = "💊 Vitamin",     ["Battery"] = "🔋 Pin", ["Lighter"] = "🔥 Bật Lửa",          -- Floor 2 Items (The Mines)     ["Bulklight"] = "🔦 Đèn Pin Sạc", ["Glowstick"] = "🧪 Đèn Rồng (Glowstick)",     ["LaserPointer"] = "🔴 Đèn Laser", ["BigBattery"] = "🔋 Pin Lớn", ["Planks"] = "🪵 Ván Gỗ",     ["StrafeSugar"] = "🍬 Kẹo Tốc Độ", ["Candy"] = "🍬 Kẹo", ["AlarmClock"] = "⏰ Đồng Hồ Báo Thức",     ["Shears"] = "✂️ Kéo Cắt Tường", ["GigaGlowstick"] = "✨ Glowstick Khổng Lồ",          -- Currency     ["Gold"] = "💰 Tiền Gold", ["Coin"] = "🪙 Tiền Xu", ["GoldPile"] = "💰 Đống Vàng" }  local MonsterAdvice = {     ["Rush"] = "Trốn vô tủ mau!", ["Ambush"] = "Trốn vô tủ mau!", ["Seek"] = "Chuẩn bị chạy trốn Seek!",     ["Screech"] = "Xoay người nhìn nó ngay!", ["Eyes"] = "Không nhìn vào nó!", ["Halt"] = "Chú ý đổi hướng di chuyển!",     ["Figure"] = "Đi cúi người (Crouch), giữ khoảng cách!", ["Hide"] = "Rời khỏi tủ ngay!", ["Jack"] = "Chờ 1 chút rồi mở lại tủ!",     ["Timothy"] = "Nhện giật mình trong hộc bàn!", ["Dread"] = "Mở cửa tiến lên phía trước mau!", ["A-60"] = "Trốn vô tủ ngay!", ["A-120"] = "Trốn vô tủ ngay!",     ["Giggle"] = "Né trần nhà ra hoặc ném Glowstick!", ["Gloombat"] = "Tắt nguồn sáng ngay!", ["Grumble"] = "Giữ khoảng cách, trốn sau vách núi!" }  -------------------------------------------------- -- HỆ THỐNG FONT SIZE REAL-TIME -------------------------------------------------- local TextSizeRegister = {} local function registerTextLabel(label)     table.insert(TextSizeRegister, label)     label.TextSize = Flags.TextSize end local function updateAllTextSizes()     for _, lbl in ipairs(TextSizeRegister) do         if lbl and lbl.Parent then lbl.TextSize = Flags.TextSize end     end end  -------------------------------------------------- -- HÀM TƯƠNG TÁC SAFE PROXIMITY PROMPT -------------------------------------------------- local function safeInteract(prompt)     if not prompt or not prompt:IsA("ProximityPrompt") or not prompt.Enabled then return false end     pcall(function()         if fireproximityprompt then             fireproximityprompt(prompt)         else             prompt:InputHoldBegin()             task.wait(prompt.HoldDuration)             prompt:InputHoldEnd()         end     end)     return true end  -------------------------------------------------- -- LOGIC AUTO MỞ TỦ & AUTO LOOT -------------------------------------------------- local activeDrawersCount = 0 local MAX_SIMULTANEOUS_DRAWERS = 3 local DRAWER_COOLDOWN = 0.6 local MAX_LOOT_DIST = 5  task.spawn(function()     while task.wait(0.05) do         if Flags.AutoDrawersLoot and LocalPlayer.Character then             local hrp = LocalPlayer.Character:FindFirstChild("HumanoidRootPart")             if hrp then                 local playerPos = hrp.Position                                  for _, prompt in ipairs(Workspace:GetDescendants()) do                     if prompt:IsA("ProximityPrompt") and prompt.Enabled then                         local parent = prompt.Parent                         if parent then                             local targetPart = parent:IsA("BasePart") and parent or parent:FindFirstChildWhichIsA("BasePart", true)                             if targetPart then                                 local dist = (targetPart.Position - playerPos).Magnitude                                 if dist <= MAX_LOOT_DIST then                                     local nameLower = parent.Name:lower()                                     local pNameLower = (parent.Parent and parent.Parent.Name:lower()) or ""                                                                          local isLootItem = nameLower:find("gold") or nameLower:find("coin") or nameLower:find("item")                                          or ImportantItems[parent.Name] or ImportantItems[parent.Parent and parent.Parent.Name or ""]                                         or prompt.ActionText:lower():find("take") or prompt.ActionText:lower():find("loot")                                         or prompt.ObjectText:lower():find("gold") or prompt.ObjectText:lower():find("coin")                                      if isLootItem then                                         safeInteract(prompt)                                     elseif (nameLower:find("drawer") or pNameLower:find("drawer") or nameLower:find("knob") or nameLower:find("closet") or nameLower:find("chest")) then                                         if activeDrawersCount < MAX_SIMULTANEOUS_DRAWERS then                                             activeDrawersCount = activeDrawersCount + 1                                             task.spawn(function()                                                 safeInteract(prompt)                                                 task.wait(DRAWER_COOLDOWN)                                                 activeDrawersCount = math.max(0, activeDrawersCount - 1)                                             end)                                         end                                     end                                 end                             end                         end                     end                 end             end         end     end end)  -------------------------------------------------- -- LOGIC AUTO MỞ CỬA BẰNG KEY -------------------------------------------------- task.spawn(function()     while task.wait(0.1) do         if Flags.AutoKeyDoor and LocalPlayer.Character then             local hrp = LocalPlayer.Character:FindFirstChild("HumanoidRootPart")             local char = LocalPlayer.Character                          local hasKey = char:FindFirstChild("Key") or char:FindFirstChild("KeyObtain") or LocalPlayer.Backpack:FindFirstChild("Key") or LocalPlayer.Backpack:FindFirstChild("KeyObtain")                          if hrp and hasKey then                 for _, obj in ipairs(Workspace:GetDescendants()) do                     if obj.Name == "Door" and obj:IsA("Model") then                         local nameLower = obj.Name:lower()                         if not nameLower:find("dupe") and not obj:FindFirstChild("DupeDoor") then                             local doorPart = obj:FindFirstChild("Door") or obj:FindFirstChildWhichIsA("BasePart")                             if doorPart then                                 local dist = (doorPart.Position - hrp.Position).Magnitude                                 if dist <= 8 then                                     local prompt = obj:FindFirstChildWhichIsA("ProximityPrompt", true)                                     if prompt and prompt.Enabled then                                         safeInteract(prompt)                                     end                                 end                             end                         end                     end                 end             end         end     end end)  -------------------------------------------------- -- TÍNH NĂNG TỐC ĐỘ, NOCLIP & BAY SÁNG TẠO -------------------------------------------------- RunService.RenderStepped:Connect(function(dt)     if LocalPlayer.Character then         local hrp = LocalPlayer.Character:FindFirstChild("HumanoidRootPart")         local humanoid = LocalPlayer.Character:FindFirstChildOfClass("Humanoid")                  if Flags.SpeedHack and hrp and humanoid and humanoid.Health > 0 then             if humanoid.MoveDirection.Magnitude > 0 then                 local extraSpeedMultiplier = Flags.SpeedMultiplier - 1                 if extraSpeedMultiplier > 0 then                     local moveDelta = humanoid.MoveDirection * (16 * extraSpeedMultiplier) * dt                     hrp.CFrame = hrp.CFrame + moveDelta                 end             end         end          if Flags.NoClip then             for _, part in ipairs(LocalPlayer.Character:GetDescendants()) do                 if part:IsA("BasePart") and part.CanCollide then part.CanCollide = false end             end         end     end end)  local flyBodyVel, flyBodyGyro = nil, nil local flyVerticalSpeed = 0  RunService.RenderStepped:Connect(function()     if Flags.FlyCarpet and LocalPlayer.Character and not Flags.FreecamSoul then         local hrp = LocalPlayer.Character:FindFirstChild("HumanoidRootPart")         local humanoid = LocalPlayer.Character:FindFirstChildOfClass("Humanoid")                  if hrp and humanoid and humanoid.Health > 0 then             if not flyBodyVel or not flyBodyVel.Parent then                 flyBodyVel = Instance.new("BodyVelocity"); flyBodyVel.MaxForce = Vector3.new(1e9, 1e9, 1e9); flyBodyVel.Parent = hrp             end             if not flyBodyGyro or not flyBodyGyro.Parent then                 flyBodyGyro = Instance.new("BodyGyro"); flyBodyGyro.MaxTorque = Vector3.new(1e9, 1e9, 1e9); flyBodyGyro.P = 9000; flyBodyGyro.Parent = hrp             end                          humanoid.PlatformStand = true             flyBodyGyro.CFrame = Camera.CFrame             local moveDir = humanoid.MoveDirection             local speed = 20 * Flags.SpeedMultiplier             flyBodyVel.Velocity = (moveDir * speed) + Vector3.new(0, flyVerticalSpeed, 0)         end     else         if LocalPlayer.Character and not Flags.FreecamSoul then             local humanoid = LocalPlayer.Character:FindFirstChildOfClass("Humanoid")             if humanoid then humanoid.PlatformStand = false end         end         if flyBodyVel then flyBodyVel:Destroy(); flyBodyVel = nil end         if flyBodyGyro then flyBodyGyro:Destroy(); flyBodyGyro = nil end         if not Flags.FreecamSoul then flyVerticalSpeed = 0 end     end end)  -------------------------------------------------- -- CHẾ ĐỘ KHẢM GIẢ / LINH HỒN TÁCH XÁC -------------------------------------------------- local freecamPart = nil local isFreecamActive = false  local function setFreecamState(state)     Flags.FreecamSoul = state     if state then         if not LocalPlayer.Character or not LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then return end         local hrp = LocalPlayer.Character.HumanoidRootPart         local humanoid = LocalPlayer.Character:FindFirstChildOfClass("Humanoid")                  if humanoid then humanoid.PlatformStand = true end         hrp.Anchored = true          if not freecamPart or not freecamPart.Parent then             freecamPart = Instance.new("Part")             freecamPart.Name = "Mote_Freecam_Soul"             freecamPart.Size = Vector3.new(0.5, 0.5, 0.5)             freecamPart.Transparency = 1             freecamPart.CanCollide = false             freecamPart.Anchored = true             freecamPart.Parent = Workspace         end         freecamPart.CFrame = Camera.CFrame          Camera.CameraSubject = freecamPart         Camera.CameraType = Enum.CameraType.Custom         isFreecamActive = true     else         isFreecamActive = false         if LocalPlayer.Character then             local hrp = LocalPlayer.Character:FindFirstChild("HumanoidRootPart")             local humanoid = LocalPlayer.Character:FindFirstChildOfClass("Humanoid")             if hrp then hrp.Anchored = false end             if humanoid then                  humanoid.PlatformStand = false                  Camera.CameraSubject = humanoid             end         end         Camera.CameraType = Enum.CameraType.Custom         if freecamPart then freecamPart:Destroy(); freecamPart = nil end     end end  RunService.RenderStepped:Connect(function(dt)     if isFreecamActive and freecamPart and LocalPlayer.Character then         local humanoid = LocalPlayer.Character:FindFirstChildOfClass("Humanoid")         local moveDir = humanoid and humanoid.MoveDirection or Vector3.new(0, 0, 0)         local speed = 25 * Flags.SpeedMultiplier                  local horizontalMove = Vector3.new(moveDir.X, 0, moveDir.Z)         local verticalMove = Vector3.new(0, flyVerticalSpeed, 0) * dt                  freecamPart.Position = freecamPart.Position + (horizontalMove * speed * dt) + verticalMove     end end)  -------------------------------------------------- -- ESP BILLBOARD GUI -------------------------------------------------- local function createBillboard(targetPart, text, color, flagName)     local billboard = Instance.new("BillboardGui")     billboard.Name = "Mote_ESP_" .. flagName     billboard.Adornee = targetPart     billboard.Size = UDim2.new(0, 160, 0, 35)     billboard.StudsOffset = Vector3.new(0, 2, 0)     billboard.AlwaysOnTop = true      local label = Instance.new("TextLabel")     label.Size = UDim2.new(1, 0, 1, 0)     label.BackgroundTransparency = 1     label.TextStrokeTransparency = 0     label.TextSize = 13     label.Font = Enum.Font.SourceSansBold     label.TextColor3 = color     label.Parent = billboard      billboard.Parent = targetPart      task.spawn(function()         while targetPart and targetPart.Parent and targetPart:IsDescendantOf(Workspace) do             if Flags[flagName] and LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then                 billboard.Enabled = true                 local dist = math.floor((LocalPlayer.Character.HumanoidRootPart.Position - targetPart.Position).Magnitude)                 label.Text = string.format("%s\n[%d studs]", text, dist)             else                 billboard.Enabled = false             end             task.wait(0.2)         end         pcall(function() billboard:Destroy() end)     end) end  -------------------------------------------------- -- ESP NGƯỜI CHƠI & DÂY NỐI TRỰC TIẾP TỪ THÂN NHÂN VẬT -------------------------------------------------- local function setupFullPlayerESP(plr)     if plr == LocalPlayer then return end      local function applyESPToCharacter(char)         if not char then return end         local hrp = char:WaitForChild("HumanoidRootPart", 5)         local head = char:WaitForChild("Head", 5)         if not hrp or not head then return end          local hl = char:FindFirstChild("Mote_Player_Highlight") or Instance.new("Highlight")         hl.Name = "Mote_Player_Highlight"         hl.FillColor = ESPColors.Player         hl.OutlineColor = Color3.fromRGB(255, 255, 255)         hl.FillTransparency = 0.5         hl.OutlineTransparency = 0         hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop         hl.Parent = char          local bb = head:FindFirstChild("Mote_Player_Billboard") or Instance.new("BillboardGui")         bb.Name = "Mote_Player_Billboard"         bb.Adornee = head         bb.Size = UDim2.new(0, 160, 0, 30)         bb.StudsOffset = Vector3.new(0, 2.5, 0)         bb.AlwaysOnTop = true          local label = bb:FindFirstChild("TextLabel") or Instance.new("TextLabel")         label.Size = UDim2.new(1, 0, 1, 0)         label.BackgroundTransparency = 1         label.TextStrokeTransparency = 0         label.Font = Enum.Font.SourceSansBold         label.TextSize = 14         label.TextColor3 = ESPColors.Player         label.Parent = bb         bb.Parent = head          local box = Drawing.new("Square")         box.Visible = fal